        body: `光と音は単位と法則のオンパレードです。「何を測る量か」を日常の感覚と結び付けて覚えましょう。

▼ゼロから：光と音の「ものさし」
・懐中電灯そのものの明るさ（光束・光度）と、照らされた机の明るさ（照度）は別の量です
・音は「エネルギーが10倍になっても、人の耳には2倍程度」にしか感じません──だから対数のdB（デシベル）を使います
・環境工学は「人がどう感じるか」を物理量に翻訳する分野です

━━━━━━━━━━━━━━━━━━━━━━
🔑 光環境の基本量
━━━━━━━━━━━━━━━━━━━━━━
・光束 F［lm］：光源から出る光の量
・光度 I［cd］：ある方向への光の強さ
・照度 E［lx］：面に入射する光束密度（1lx = 1lm/m²）
・輝度 L［cd/m²］：面の見かけの明るさ（グレアに関係）
・距離の逆2乗法則：点光源直下の照度は距離の2乗に反比例

【図解】光の4つの量の関係（懐中電灯モデル）
光束lm　＝電灯から出る「光の総量」（水道でいう毎分の水量）
光度cd　＝ある方向への「光の勢い」
照度lx　＝机に届いた「明るさ」＝受け取る側の量
輝度cd/m²＝机や画面が「輝いて見える」度合い＝目に入る量
→照度は「照らされる側」、輝度は「見える側」。まぶしさ（グレア）は輝度の問題

■ 昼光利用
・昼光率 D = 室内のある点の照度 ÷ 全天空照度 ×100［%］
・昼光率は天候・時刻によらず一定（直射日光は含めない）
・側窓は奥行き方向に照度分布の差が大きい。天窓（トップライト）は同面積の側窓より採光上有効

━━━━━━━━━━━━━━━━━━━━━━
🔑 音環境
━━━━━━━━━━━━━━━━━━━━━━
・音の強さのレベル：10dB 増えると音の強さ（エネルギー）は10倍
・同じ音圧レベルの音源を2つ合成すると +3dB
・音の可聴周波数：約20Hz〜20kHz。周波数が2倍で「1オクターブ」
・残響時間：音源停止後、音圧レベルが 60dB 低下するまでの時間
　セービンの式：残響時間は室容積に比例し、吸音力に反比例
・遮音等級：壁は D値（大きいほど良い）、床衝撃音は L値（小さいほど良い）
・コインシデンス効果：特定周波数で板材の遮音性能が低下する現象

【図解】dB計算の早見表
・同じ音2つの合成：＋3dB（エネルギー2倍）
・エネルギー10倍：＋10dB
・エネルギー100倍：＋20dB
・点音源から距離2倍：−6dB（自由空間）
→dBは「掛け算を足し算に変えた」単位。10倍ごとに+10dBが基本

【図解】遮音の2大指標 D値とL値
◎D値（壁の遮音等級）：大きいほど遮音性能が良い（Dr-50＞Dr-40）
◎L値（床衝撃音レベル）：小さいほど遮音性能が良い（LH-45＜LH-50が優秀）
×「L値が大きい＝良い」と覚えると逆──Lは下階で「聞こえる音」の大きさ
→軽量床衝撃音（スリッパ音）＝カーペット等の仕上げで改善
→重量床衝撃音（子どもの飛び跳ね）＝スラブを厚く・重くして改善

■ 吸音と遮音は別物
・吸音材（グラスウール等の多孔質材）：音を吸収し室内の響きを抑える。高音域に有効
・遮音：音を透過させない。質量則──面密度（重さ）が大きいほど遮音性能が高い
・多孔質吸音材は「軽い」ので遮音性能はほとんどない（頻出）

━━━━━━━━━━━━━━━━━━━━━━
🔑 室内空気環境・温熱環境
━━━━━━━━━━━━━━━━━━━━━━
■ 温熱環境の6要素
・物理側4要素：気温・湿度・気流・放射（周壁温度）
・人間側2要素：代謝量（met）・着衣量（clo）
・PMV（予測平均温冷感申告）：6要素から快適性を予測。-0.5〜+0.5が推奨域
・作用温度（OT）：気温と放射の総合指標。放射暖冷房の評価に有効

■ 空気の汚染物質
・CO₂：人体の呼吸由来。空気清浄度の代表指標（1000ppm以下）
・CO：不完全燃焼で発生。毒性が強い（基準6ppm以下）
・ホルムアルデヒド：建材・家具由来。シックハウスの原因（0.1mg/m³以下）
・浮遊粉じん：0.15mg/m³以下

【図解】温熱快適性の6要素
環境側：気温／湿度／気流／放射（壁・窓の表面温度）
人間側：代謝量met（活動の激しさ）／着衣量clo（服の厚さ）
→「エアコンの設定温度が同じでも窓際が寒い」のは放射（コールドドラフト）のせい
→PMVはこの6要素を統合した指標。ISOで規格化されている

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算実践：光束法による照度計算
━━━━━━━━━━━━━━━━━━━━━━
・照度計算の基本式：E = F × N × U × M ÷ A
　E：平均照度［lx］、F：1灯あたりの光束［lm］、N：灯数、U：照明率、M：保守率、A：床面積［m²］
・照明率U：器具・室の形状（室指数）や反射率で決まる係数（0〜1）
・保守率M：時間経過による光束減退・汚れを見込む係数（一般に0.6〜0.8程度で計画）

例題：床面積100m²の事務室を平均照度750lxにしたい。1灯あたり3,200lmのLED器具、照明率0.6、保守率0.7とすると
・必要灯数 N = E×A ÷（F×U×M）= 750×100 ÷（3,200×0.6×0.7）= 75,000 ÷ 1,344 ≒ 55.8 → 56灯

【図解】光束法計算のチェックポイント
手順1：目標の平均照度E［lx］と面積A［m²］を決める（用途基準に沿って設定）
手順2：器具の光束F・照明率U・保守率Mを確認する
手順3：N=E×A÷(F×U×M) で灯数を求め、切り上げる
→保守率Mが小さいほど（汚れやすい環境ほど）必要灯数は増える
→照明率Uは天井が高い・室が細長い（室指数が小さい）ほど低下し、必要灯数が増える

【図解】遮音等級を実務で読む
D値（壁）：Dr-40 の界壁とDr-50 の界壁を比べると、Dr-50の方が数値が大きく遮音性能が高い
L値（床）：LH-55（重量床衝撃音）はLH-45より数値が大きく、下階に伝わる音が大きい＝性能が低い
→集合住宅の管理規約等で「LH-55等級以上」等と要求水準が示されることがある
→設備配管が界壁・床スラブを貫通する箇所は、遮音等級を満たすための隙間処理・防振材の検討が必要になる

⚠ ひっかけ注意
・照度は「受照面」の量、輝度は「発光・反射面」の量──定義の入れ替えが定番
・昼光率に直射日光は含まない（天空光のみ）
・吸音材は遮音しない。遮音は質量（重さ）で決まる
・残響時間の定義は「60dB」低下（50dBや30dBではない）
・D値は大きいほど良い／L値は小さいほど良い──向きが逆

★ここだけ暗記
・1lx = 1lm/m²、点光源の照度は距離の2乗に反比例
・+3dB＝2倍、+10dB＝10倍（エネルギー）
・残響時間∝室容積/吸音力（セービン）
・PMV推奨域：-0.5〜+0.5、6要素＝気温・湿度・気流・放射・代謝・着衣`,
