        body: `建物は竣工してからが「本番」です。長く安全・快適に使い続けるための維持保全・ファシリティマネジメント（FM）の考え方を学びます。

▼ゼロから：建物も「健康診断」と「メンテナンス」が必要
・人間が定期的に健康診断を受けるように、建物・設備も定期的な点検・保守が欠かせません
・放置すれば劣化が進み、いずれ大きな故障や事故につながります。「壊れてから直す」のではなく「壊れる前に手入れする」という発想が保全の基本です
・ファシリティマネジメント（FM）は、この保全活動を、コスト・利便性・経営戦略まで含めて総合的にマネジメントする考え方です

━━━━━━━━━━━━━━━━━━━━━━
🔑 保全の3つの方式
━━━━━━━━━━━━━━━━━━━━━━
・事後保全：故障・不具合が発生してから修理・対応する方式。対応は簡単だが、突発的な機能停止のリスクがある
・予防保全（時間基準保全）：一定の周期（時間・使用時間等）ごとに、故障の有無にかかわらず点検・部品交換を行う方式
・予知保全（状態基準保全）：センサー等で機器の状態（振動・温度・劣化兆候等）を常時監視し、異常の兆候が現れたタイミングで対応する方式
・重要度の高い設備（防災用設備・基幹インフラ等）ほど、事後保全ではなく予防保全・予知保全へ移行することが望ましい

【図解】3つの保全方式の考え方の違い
◎事後保全：壊れてから直す（シンプルだが突発停止のリスク大）
◎予防保全：決めた周期で必ず手入れする（計画は立てやすいが、まだ壊れていない部品も交換しコストがかさむことがある）
◎予知保全：状態を監視し、壊れる兆候が出たら対応する（無駄が少ないが、監視システムの導入コストがかかる）
→BEMS・IoTセンサー（kucho-08既出）の普及により、予知保全への移行が近年進んでいる
→防災設備（消火ポンプ・非常用発電機等）は、突発停止が許されないため予防保全が基本となる

━━━━━━━━━━━━━━━━━━━━━━
🔑 長期修繕計画
━━━━━━━━━━━━━━━━━━━━━━
・長期修繕計画：建物・設備の主要な部位・機器について、将来の更新・大規模修繕の時期と概算費用をあらかじめ計画したもの
・機器ごとに一般的な更新周期の目安があり、これを踏まえて計画を立てる（機器の種類・使用条件によって実際の寿命は変動する）
・修繕積立金：集合住宅等では、将来の大規模修繕に備えて区分所有者から計画的に積み立てる仕組みが一般的
・長期修繕計画は定期的に見直し、実際の劣化状況・物価変動等を反映して更新することが望ましい

【図解】長期修繕計画がないとどうなるか
×計画なし：急な故障のたびに場当たり的な予算確保→高額な緊急対応費用が発生しやすい
○計画あり：更新時期を事前に予測し、予算を平準化して積み立て→計画的な予算執行が可能
→LCC（ippan-11既出）の考え方を、時間軸に沿って具体的な実行計画に落とし込んだものが長期修繕計画
→計画があることで、大規模修繕のタイミングで複数の工事をまとめて行い、コストを抑える工夫もしやすくなる

━━━━━━━━━━━━━━━━━━━━━━
🔑 ファシリティマネジメント（FM）の視点
━━━━━━━━━━━━━━━━━━━━━━
・FM：建物・設備等の施設（ファシリティ）を、経営資源の一つとして総合的・戦略的に管理・活用する考え方
・単なる「維持保全」を超えて、スペースの有効活用、コスト最適化、働き方の変化への対応等、経営的な視点を含む
・JFMA（日本ファシリティマネジメント協会）等の団体が、FMの考え方・資格制度の普及を進めている
・建築設備士は、FMの実行段階で「設備をどう維持し、どう更新するか」という専門知識を提供する役割を担う

⚠ ひっかけ注意
・事後保全は「対応が簡単」だが「突発的な機能停止リスクが高い」──重要設備には不向き
・予防保全は「まだ壊れていない部品も交換する」ことがあり、必ずしも最もコストが安い方式ではない
・予知保全の導入には、監視システム（センサー等）への初期投資が必要
・長期修繕計画は一度作ったら終わりではなく、定期的な見直しが必要
・FMは「維持保全」よりも広い概念で、コスト最適化やスペース活用等の経営的視点を含む

★ここだけ暗記
・保全方式：事後保全（壊れてから）／予防保全（周期で）／予知保全（状態監視で）
・重要設備（防災用等）は事後保全ではなく予防保全が基本
・長期修繕計画＝将来の更新時期・費用を事前に計画し、予算を平準化する仕組み
・FM＝維持保全を超えた、施設を経営資源として総合的に管理する考え方`,
