━━━━━━━━━━━━━━━━━━━━━━
・建築確認等の権限を持つ建築主事・特定行政庁・指定確認検査機関は、確認等を行う前に、その建築物の工事施工地または所在地を管轄する消防長または消防署長の同意を得なければならない
