◎陽圧（周囲より気圧を高くし、外気の侵入を防ぐ）：手術室、ICU、易感染患者の病室
◎陰圧（周囲より気圧を低くし、室内空気の流出を防ぐ）：感染症病室、結核病室、検査室（培養）
→「きれいな空気を守る＝陽圧」「汚い空気を閉じ込める＝陰圧」で覚える
