        emoji: '🚗',
        body: `建物の規模によっては、駐車場の設置そのものが法律上の義務になります。駐車場・自転車駐車場の附置義務と、換気・防災上の関連知識を整理します。

▼ゼロから：車社会を支える「隠れた義務」
・大規模な建物を建てると、その利用者の車がまちの道路にあふれてしまうことがあります
・これを防ぐため、一定規模以上の建物には、敷地内または近隣に駐車場を確保する「附置義務」が条例等で定められています
・駐車場は「閉鎖的な空間に自動車の排気ガスがたまる」特殊な室のため、換気設計にも独自のルールがあります

━━━━━━━━━━━━━━━━━━━━━━
🔑 駐車場法と附置義務制度
━━━━━━━━━━━━━━━━━━━━━━
・駐車場法：都市における駐車施設の整備を目的とする法律。路外駐車場の構造・設備基準等を定める
・附置義務駐車施設：地方公共団体の条例により、一定規模以上の建築物に対して、その用途・規模に応じた台数の駐車施設の設置を義務付ける制度
・附置義務の具体的な必要台数・対象規模は、地域や条例によって異なるため、計画地の条例確認が実務上不可欠
・自転車駐車場についても、同様の附置義務条例（自転車の安全利用の促進及び自転車等の駐車対策の総合的推進に関する法律に基づく条例等）が定められることがある

【図解】附置義務制度の目的と仕組み
建物の利用者が車で来る→駐車場がないと道路に路上駐車が発生→交通渋滞・事故のリスク増加
○条例で「建物の規模に応じた駐車台数」を附置義務として設定→路上駐車の発生を抑制
→附置義務は建築確認とは別に、地方公共団体の条例に基づく手続きが必要になることが多い
→大規模な商業施設・オフィスビルほど、附置義務の必要台数が多くなる傾向がある

━━━━━━━━━━━━━━━━━━━━━━
🔑 駐車場の換気設計（建築設備との接点）
━━━━━━━━━━━━━━━━━━━━━━
・自動車の排気ガス（一酸化炭素・窒素酸化物等）が滞留しないよう、地下・屋内駐車場には強制換気設備が必要になることが多い
・換気量は駐車台数・床面積等から算定し、排気ガス濃度が一定の基準以下に保たれるよう設計する
・駐車場は消防法上、火災の発生源（自動車火災）としても扱われ、泡消火設備・水噴霧消火設備等の油火災対応の消火設備（既出）が設置されることが多い
・駐車場の防火区画・竪穴区画（車路が複数階にまたがる場合）の取り扱いにも注意が必要

【図解】駐車場特有の設備要求
○換気：排気ガス濃度管理のための強制換気（一酸化炭素等の基準値以下を維持）
○消火：油火災（B火災）対応の泡消火・水噴霧消火設備（既出のkyuhaisui-04と直結）
○区画：車路が複数階をつなぐ場合、竪穴区画の考え方（bousai-04既出）が関わる
→駐車場は「排気ガスがこもりやすい」「油火災のリスクがある」という2つの特殊性を持つ室として設計する
→機械式駐車場（立体駐車場）では、換気・消火に加えて構造・安全装置の技術基準も別途関わる

━━━━━━━━━━━━━━━━━━━━━━
🔑 荷捌き施設・附置義務との関係
━━━━━━━━━━━━━━━━━━━━━━
・大規模な物販店舗等では、荷物の搬出入のための荷捌き駐車施設の確保も条例等で求められることがある
・荷捌き駐車施設は、一般来客用の駐車場とは別に計画され、トラック等の大型車両の動線・回転スペースを考慮する
・地域によっては、荷捌き車両の搬出入時間帯の制限（近隣配慮）が条例で定められることもある

⚠ ひっかけ注意
・附置義務駐車施設の必要台数・対象規模は全国一律ではなく、地方公共団体の条例によって異なる
・駐車場の換気は「排気ガス濃度の管理」が目的であり、一般居室の必要換気量算定式（令20条の2）とは異なる考え方で計画される
・駐車場の消火設備は油火災（B火災）対応が基本で、一般的な水系消火設備（棒状放水）だけでは不十分な場合がある
・附置義務は建築確認手続とは別に、条例に基づく手続きが必要になることが多い
・機械式駐車場は換気・消火に加えて、構造・安全装置に関する別の技術基準が関わる

★ここだけ暗記
・附置義務駐車施設＝地方公共団体の条例に基づく、建物規模に応じた駐車台数の設置義務
・駐車場の換気＝排気ガス濃度管理が目的の強制換気
・駐車場の消火＝油火災（B火災）対応の泡・水噴霧消火設備が基本
・荷捌き駐車施設は一般駐車場と別枠で計画されることがある`,
