        body: `hoki-01で学んだ建築基準法12条の定期調査・検査報告制度を、対象建築物の考え方から実務まで掘り下げます。「誰が・何を・いつ報告するか」を体系的に理解します。

▼ゼロから：「作った後」を法律がフォローする仕組み
・建築確認は「作る前」のチェック、完了検査は「作った直後」のチェックですが、建物は何十年も使われ続けます
・その間、劣化や不適切な使用により安全性が損なわれていないかを定期的に確認する仕組みが、12条の定期報告制度です
・「一度合格したら終わり」ではなく「使い続ける限り、繰り返し確認する」という発想がこの制度の本質です

━━━━━━━━━━━━━━━━━━━━━━
🔑 定期報告制度の全体構成
━━━━━━━━━━━━━━━━━━━━━━
・建築物本体の定期調査：特定行政庁が指定する特定建築物（不特定多数が利用する用途・一定規模以上の建築物等）について、敷地・構造・防火に関する状態を定期的に調査し報告する
・建築設備の定期検査：換気設備・排煙設備・非常用照明・給排水設備等について、正常に機能するかを定期的に検査し報告する（hoki-01既出）
・防火設備の定期検査：防火戸・防火シャッター等の防火設備が正常に閉鎖・作動するかを定期的に検査し報告する
・昇降機等の定期検査：エレベーター・エスカレーター等について、安全装置を含めた機能を定期的に検査し報告する（bousai-05既出）

【図解】4種類の定期報告の対象範囲
◎建築物本体：敷地・構造・防火区画等の状態（避難施設の維持状況等も含む）
◎建築設備　：換気・排煙・非常用照明・給排水（機能するかどうか）
◎防火設備　：防火戸・防火シャッター等（正しく閉鎖・作動するか）
◎昇降機等　：エレベーター・エスカレーターの安全装置を含む機能
→「建物」「設備」「防火設備」「昇降機」という4つの対象に分かれ、それぞれ別々に報告される
→建築設備士が最も深く関わるのは、このうち「建築設備」の定期検査領域

━━━━━━━━━━━━━━━━━━━━━━
🔑 対象建築物の考え方
━━━━━━━━━━━━━━━━━━━━━━
・特定行政庁が、用途・規模（床面積・階数等）に応じて、報告を義務付ける対象建築物を指定する
・不特定多数の人が利用する用途（劇場・百貨店・ホテル等、hoki-04で学んだ特定防火対象物と類似の発想）、避難が困難な人が利用する用途（病院・老人ホーム等）が対象になりやすい
・対象建築物の具体的な範囲（用途・規模の線引き）は特定行政庁ごとに定められ、必ずしも全国一律ではない点に注意が必要
・共同住宅は、規模によっては建築物本体の定期調査の対象になることがある（消防法上は非特定防火対象物であることと対比して理解する）

━━━━━━━━━━━━━━━━━━━━━━
🔑 検査資格者と報告の実務
━━━━━━━━━━━━━━━━━━━━━━
・建築物調査員・建築設備検査員・防火設備検査員・昇降機等検査員：それぞれの定期報告の調査・検査を行う資格者（一級・二級建築士がこれらの資格を取得することも多い）
・検査結果は、所有者・管理者から特定行政庁へ報告される。報告を怠ると是正指導・行政処分の対象になりうる
・調査・検査で不具合が発見された場合、報告書にその内容を記載し、必要な改善（修繕等）を促す仕組みになっている
・建築設備士は、設計・施工段階の知見を活かし、建築設備検査員としての実務にも関わることができる

⚠ ひっかけ注意
・定期報告は「建築物本体」「建築設備」「防火設備」「昇降機等」の4種類に分かれ、それぞれ別の検査対象・検査資格者が関わる
・対象建築物の具体的な範囲は特定行政庁ごとに定められ、全国一律ではない
・建築設備の定期検査対象は「換気・排煙・非常用照明・給排水」（hoki-01既出）であり、空調設備そのものは対象に含まれないことに注意
・消防法の点検報告（特定1年・非特定3年、hoki-04既出）と建築基準法12条の定期報告は、根拠法も対象も異なる別制度
・検査で不具合が見つかった場合は、報告するだけでなく必要な改善につなげることが制度の趣旨

★ここだけ暗記
・12条定期報告の4種類：建築物本体／建築設備／防火設備／昇降機等
・建築設備の対象＝換気・排煙・非常用照明・給排水（空調設備そのものは対象外）
・対象建築物の範囲は特定行政庁ごとに指定され、全国一律ではない
・消防法の点検報告制度とは根拠法・対象が異なる別制度`,
