        emoji: '🔋',
        body: `熱を「今つくる」のではなく「安く作れる時間にためて、必要な時に使う」──蓄熱の発想と、広域で熱を融通する地域冷暖房を学びます。

▼ゼロから：電気は「ためにくい」が熱は「ためやすい」
・電気は大量に蓄えるのが難しく高価ですが、水や氷の形にすれば熱は比較的安く大量に蓄えられます
・夜間の電力（一般に安価）で氷や温水をつくり、昼間の冷房ピークに使う──これが蓄熱システムの基本発想です
・地域冷暖房は、この「熱をつくる場所」を建物ごとから街区単位にまとめる考え方です

━━━━━━━━━━━━━━━━━━━━━━
🔑 蓄熱システムの種類
━━━━━━━━━━━━━━━━━━━━━━
・水蓄熱：水の顕熱（比熱4.2kJ/(kg・K)）を利用。7℃前後の冷水・50℃前後の温水として蓄える
・氷蓄熱：水の潜熱（凝固・融解、約334kJ/kg）を利用。同じ体積でより多くの熱を蓄えられる
・氷蓄熱は水蓄熱に比べて蓄熱槽を小型化できるが、氷を作る分だけ冷凍機の蒸発温度が低くなり、COPは低下する
・躯体蓄熱：建物の躯体（コンクリート）自体を蓄熱体として利用する方式

【図解】水蓄熱と氷蓄熱の比較
◎水蓄熱：顕熱利用（比熱4.2kJ/(kg・K)）→槽は大きくなるが冷凍機の運転効率は高い（蒸発温度が高め）
◎氷蓄熱：潜熱利用（約334kJ/kg、顕熱の約80倍）→槽を小型化できるが、氷を作るため冷凍機の蒸発温度を下げる必要がありCOPは下がる
→「槽を小さくしたい→氷蓄熱、効率を優先したい→水蓄熱」という設計判断のトレードオフ
→潜熱（334kJ/kg）は顕熱（4.2kJ/(kg・K)×1K）の約80倍──同じ重さで運べる熱量が桁違いに大きい

■ 蓄熱システムのメリット
・熱源機器の容量を「その日のピーク負荷」ではなく「1日の平均的な熱量」に近づけて小型化できる
・夜間電力の活用による運転コストの低減（電力料金体系による）
・停電時にも蓄えた熱で一定時間の空調継続が可能（BCP上のメリット）
・熱源機の連続運転により、部分負荷運転を減らし機器効率を安定させられる

━━━━━━━━━━━━━━━━━━━━━━
🔑 ヒートポンプの効率指標
━━━━━━━━━━━━━━━━━━━━━━
・COP（成績係数）：ある運転条件における「出力（冷暖房能力）÷入力（消費電力）」の瞬時値
・APF（通年エネルギー消費効率）：1年を通じた冷暖房負荷に対する消費電力量の比。実使用に近い評価指標
・ヒートポンプは電気ヒーターと異なり、大気中や地中の熱を「くみ上げる」ため、COPが1を大きく超える（投入電力の何倍もの熱を運べる）
・外気温が低いほど（暖房時）空気熱源ヒートポンプの能力・COPは低下する（着霜・デフロストの影響も含む）
・地中熱・水熱源ヒートポンプは年間を通じた熱源側温度が安定しており、空気熱源より高効率になりやすい

【図解】COPとAPFの違い
◎COP：ある瞬間・ある条件での効率（カタログのピーク値になりやすい）
◎APF：1年間の負荷パターンを織り込んだ通年での効率（実際の省エネ性能に近い）
→「COPが高い機種＝年間を通じて省エネ」とは限らない。実態評価にはAPFを見る
→空気熱源ヒートポンプの暖房COPは外気温低下とともに下がる（寒冷地で不利になりやすい理由）

━━━━━━━━━━━━━━━━━━━━━━
🔑 地域冷暖房（DHC：District Heating and Cooling）
━━━━━━━━━━━━━━━━━━━━━━
・熱源プラントを街区に1か所（または数か所）集約し、地域導管を通じて複数の建物に冷水・温水・蒸気を供給する仕組み
・各建物は個別の熱源機器を持たず（または最小限とし）、熱交換器を介して熱を受け取る
・メリット：大型・高効率機器の集約導入、個別建物の熱源スペース削減、大気汚染物質の排出源集約による環境負荷低減
・デメリット：導管の敷設・維持コストが大きい、熱の融通先が偏ると非効率、個別最適な制御がしにくい面がある
・未利用エネルギー（河川水・下水熱・地中熱等）の活用は地域冷暖房と組み合わせやすい

【図解】個別熱源方式と地域冷暖房方式の比較
◎個別熱源：建物ごとに熱源機器を設置。自由度が高いが、建物ごとに機械室・スペースが必要
◎地域冷暖房：街区の熱源プラントから配管で熱を供給。各建物は熱交換器で受け取るだけでよく、機械室が縮小できる
→大規模再開発・都市部のオフィス街区で採用例が多い
→建物側の設備計画では「熱源機器」ではなく「熱交換器と二次側ポンプ」が主な検討対象になる

⚠ ひっかけ注意
・氷蓄熱は槽を小型化できるが、冷凍機の蒸発温度を下げるためCOPは低下する（「氷蓄熱は常に高効率」は誤り）
・COPは瞬時値、APFは通年値──省エネ性能の実態比較にはAPFを用いる
・地域冷暖房は「各建物の熱源機器が不要になる」が「熱交換器等の設備まで不要になる」わけではない
・水の潜熱（融解熱約334kJ/kg）は顕熱よりはるかに大きい──氷蓄熱が小型化できる理由の根拠
・地中熱・水熱源は空気熱源より年間の熱源側温度が安定しており、一般に効率面で有利

★ここだけ暗記
・水蓄熱＝顕熱利用（4.2kJ/(kg・K)）／氷蓄熱＝潜熱利用（約334kJ/kg、槽小型化・COPは低下）
・COP＝瞬時効率、APF＝通年効率（実態評価はAPF）
・地域冷暖房＝街区で熱源集約、建物側は熱交換器中心の設備計画になる
・ヒートポンプは大気・地中の熱をくみ上げるためCOP＞1が基本原理`,
