        emoji: '🖥️',
        body: `建物が完成した後の「運用」フェーズで省エネ・快適性を作り込むのがBEMSとコミッショニングです。設計だけでなく運用まで見通す視点が問われます。

▼ゼロから：家計簿をつけると節約できるのと同じ
・電気やガスの使用量を「見える化」するだけで、無駄遣いに気づいて節約できることがあります
・BEMS（Building Energy Management System）は、建物版の家計簿兼自動節約システムです
・センサーで集めたデータを分析し、機器の運転を自動で最適化するところまでを含みます

━━━━━━━━━━━━━━━━━━━━━━
🔑 BEMSの機能
━━━━━━━━━━━━━━━━━━━━━━
・計測（メータリング）：電力・ガス・水道・熱量を用途別・系統別に計測
・見える化：使用量をグラフ等で可視化し、異常な増加（漏水・機器の不調等）に気づきやすくする
・監視・制御：空調・照明・熱源等の運転状態を中央で監視し、スケジュール運転・遠隔制御を行う
・デマンド監視・制御：契約電力（デマンド値）を超えないよう、優先順位の低い負荷を自動的に抑制する
・最適起動・停止制御：外気温度や蓄熱状況から、目標時刻に室温が整うよう予冷・予熱の開始時刻を自動計算する

【図解】BEMSの機能ピラミッド
①計測（メータリング）：まず測る（用途別・系統別）
②見える化：測った値をグラフ化・異常検知
③制御：スケジュール運転・デマンド制御・最適起動停止
④分析・改善（コミッショニング）：データを基に運用改善を継続
→「測る→見る→制御する→改善する」の順で機能が積み上がる
→計測なくして制御なし、というのがBEMS導入の第一原則

━━━━━━━━━━━━━━━━━━━━━━
🔑 デマンド制御
━━━━━━━━━━━━━━━━━━━━━━
・デマンド値：一般に30分ごとの平均使用電力。契約電力（基本料金）はこのデマンド値の年間最大値で決まることが多い
・デマンド制御：デマンド値が目標を超えそうな場合、優先度の低い機器（一部の空調・照明等）を自動的に間引き運転する
・デマンドが一度でも跳ね上がると、その後長期間（契約形態によっては1年間）基本料金が高止まりすることがある
・蓄熱システム（kucho-07）と組み合わせると、昼間のデマンドピークを蓄えた熱でまかない、さらに抑制できる

【図解】デマンド制御の考え方
契約電力＝過去のデマンド値の最大値で決まる（一度の跳ね上がりが長く尾を引く）
○デマンド制御：ピークが近づいたら優先度の低い負荷を自動的に抑制→ピークそのものを作らない
○蓄熱との連携：昼間のピーク負荷を夜間に蓄えた熱でカバーし、電力ピークを平準化（ピークシフト）
→「省エネ（総量を減らす）」と「ピークカット（山を削る）」は別の効果──料金設計上はピークカットも重要

━━━━━━━━━━━━━━━━━━━━━━
🔑 コミッショニング（性能検証）
━━━━━━━━━━━━━━━━━━━━━━
・コミッショニング：設計意図どおりに建物・設備が性能を発揮しているかを、竣工前後を通じて検証・調整するプロセス
・竣工時コミッショニング：試運転調整（TAB：試験・調整・バランシング）を含め、設計性能が出ているかを確認
・継続的コミッショニング：運用開始後もBEMSデータを使い、経年劣化・使い方の変化に応じて継続的に調整する
・「設計性能どおりに完成しても、運用でずれていく」ことを前提に、定期的な見直しの仕組みを組み込む考え方

■ スマートビルの発展要素
・IoTセンサーによるきめ細かい環境計測（在室検知・CO₂・温湿度分布等）
・AIによる需要予測・自動制御の高度化（予測制御）
・他システムとの連携（入退室管理、エレベーター運行、駐車場等）による全体最適化
・オープンプロトコル（BACnet等）による異なるメーカー機器間の相互接続性確保

【図解】コミッショニングのタイムライン
設計時：性能目標を明確に設定
↓
竣工時：試運転調整（TAB）で設計性能どおりかを検証
↓
運用開始後：BEMSデータで継続的に監視・調整（継続的コミッショニング）
→「作って終わり」ではなく「動かしながら性能を維持・改善し続ける」のがコミッショニングの本質
→省エネ法のBEI計算（設計値）と実際の運用値は乖離しうる──この差を埋める役割もBEMSが担う

⚠ ひっかけ注意
・デマンド値は瞬時最大ではなく「一定時間（一般に30分）の平均使用電力」で評価される
・デマンド制御は「省エネ」そのものではなく「ピークを作らない」ための制御（総使用量は変わらないこともある）
・BEMSは「見える化するだけ」の道具ではない──制御・最適化まで含むシステム
・コミッショニングは竣工検査だけでなく、運用開始後も継続する取り組み（継続的コミッショニング）
・オープンプロトコル（BACnet等）を使わないと、異なるメーカー機器を一元管理しにくい

★ここだけ暗記
・BEMS＝計測→見える化→制御→改善の4段階、デマンド制御と最適起動停止が代表機能
・デマンド値＝一定時間（一般に30分）平均電力、契約電力はその最大値で決まりやすい
・コミッショニング＝設計意図どおりの性能を竣工時・運用時を通じて検証・調整する取り組み
・蓄熱＋デマンド制御でピークシフトが可能（省エネとピークカットは別概念）`,
