        emoji: '🌀',
        body: `「換気量を確保した」だけでは快適な室内環境とは限りません。空気がどう流れ、どこに新鮮空気が届いているかを評価する指標を学びます。

▼ゼロから：換気量が同じでも「効き方」は違う
・同じ量の外気を入れても、部屋の隅に淀み（デッドスペース）ができれば、そこは実質的に換気されていません
・扇風機の前だけ涼しくて部屋の奥が暑いように、空気の「量」だけでなく「流れ方」が快適性を左右します
・この「流れ方の良し悪し」を数値で評価するのが換気効率・気流分布の指標です

━━━━━━━━━━━━━━━━━━━━━━
🔑 換気効率の指標
━━━━━━━━━━━━━━━━━━━━━━
・換気回数だけでは室内の空気の「入れ替わり方」までは分からない（理論上の平均値にすぎない）
・局所換気効率：室内のある地点に、新鮮空気がどれだけ効率的に届いているかを表す指標
・混合換気（一般的な空調）：給気と室内空気がよく混ざり合う方式。設計・制御は容易だが、局所的な効率は中程度
・置換換気：温度差による自然な上昇気流を利用し、床面近くから低温の新鮮空気を供給、汚染空気を天井付近から排出する方式
・置換換気は居住域（人がいる高さ）の空気質を効率的に保ちやすいが、負荷が大きい室では温度成層が崩れやすい

【図解】混合換気と置換換気の空気の流れ方
◎混合換気：給気を室内でよく攪拌→室全体がほぼ均一な濃度・温度になる（一般的な天井吹出し）
◎置換換気：床付近から低速で給気→温度差で上昇→天井付近で排気（成層化した流れ）
→混合換気は「薄めて全体をきれいにする」、置換換気は「きれいな空気を下から押し上げる」という発想の違い
→置換換気は工場・劇場等、天井が高く汚染源が明確な空間で特に効果を発揮する

━━━━━━━━━━━━━━━━━━━━━━
🔑 気流と温熱快適性の関係
━━━━━━━━━━━━━━━━━━━━━━
・ドラフト（不快気流）：気流速度が大きすぎると、体感温度が下がりすぎて不快に感じる現象
・コールドドラフト：冷たいガラス面付近で発生する下降気流。窓際の座席で足元が冷える原因
・ADPI（Air Diffusion Performance Index）：室内の温度・気流分布の快適性を評価する指標の一つ
・吹出口の選定（誘引比の大きい吹出口等）により、室内気流の均一性を高め、コールドドラフトを抑制できる

【図解】コールドドラフトが起きる仕組みと対策
①冬季、窓ガラスの室内側表面が外気で冷やされる
②窓際の空気がガラスに触れて冷やされ、重くなって下降する
③床面を這うように冷気が室内側へ流れ込み、足元が冷える
→対策：窓際に暖房（放熱器・ファンコイル）を設置して上昇気流を作る、断熱性能の高い窓（Low-E複層ガラス等）を採用する
→ippan-03で学んだ断熱・結露の知識と、この気流の知識は表裏一体の関係にある

⚠ ひっかけ注意
・換気回数が同じでも、換気効率（実際の入れ替わりの良さ）は換気方式によって異なる
・置換換気は「負荷の小さい室」で効果を発揮しやすく、負荷が大きすぎると温度成層が乱れて効果が低下する
・コールドドラフトは「窓ガラスが冷たいこと」自体ではなく、それによって生じる「下降気流」が不快感の直接の原因
・混合換気は室内を均一化するのが目的であり、局所的な空気質の効率という点では置換換気に劣ることがある

★ここだけ暗記
・混合換気＝攪拌して均一化、置換換気＝床から給気し温度差で押し上げる
・置換換気は天井の高い空間・汚染源が明確な空間で効果的
・コールドドラフト＝冷たい窓面で生じる下降気流が原因（対策は窓際の暖房・高断熱窓）
・換気「量」だけでなく換気「効率」（気流分布）が室内環境の質を左右する`,
