        body: `水を大量に扱う室、天井が高く大人数が集まる室は、それぞれ特有の空調上の課題を抱えます。代表的な特殊空間の設計要点を学びます。

▼ゼロから：水がある部屋は「結露との戦い」
・プールや浴場は、水面から絶えず水蒸気が発生し続ける特殊な環境です
・一般の事務室と同じ感覚で空調すると、窓・天井・壁が結露だらけになり、カビや構造体の腐食を招きます
・「発生し続ける水蒸気をどう処理するか」がこの分野の設計テーマです

━━━━━━━━━━━━━━━━━━━━━━
🔑 プール・浴場の空調
━━━━━━━━━━━━━━━━━━━━━━
・水面からの蒸発負荷：水温・気温・気流・水面積によって決まる大きな潜熱負荷源
・室内は高湿度になりやすく、天井面・鉄骨等の低温部で結露しやすい（金属部の腐食にもつながる）
・除湿方式：デシカント除湿、冷却除湿（コイルで除湿）、外気導入による希釈等を組み合わせる
・プール室特有の腐食対策：塩素ガス・高湿度環境に耐える耐食性の高い機器・ダクト材料を選定する

【図解】プール室で結露・腐食が起きやすい理由
①水面から絶えず水蒸気が発生（一般の居室にはない持続的な潜熱源）
②天井・鉄骨等、外気に近く温度が下がりやすい部位で結露が発生
③塩素消毒由来のガスが金属部を腐食させる（プール特有の腐食環境）
→「高湿度」と「腐食性ガス」の両方に耐える設計が必要な、特殊な環境ということを踏まえる
→天井を高くして水蒸気を拡散させる、天井面の温度を上げる（断熱強化）等の建築的な対策と併用する

━━━━━━━━━━━━━━━━━━━━━━
🔑 体育館・アリーナ等の大空間空調
━━━━━━━━━━━━━━━━━━━━━━
・天井が高く容積が大きいため、居住域（人がいる高さ）だけを効率的に空調する発想が重要
・成層空調・床吹出し空調：床面近くから空調し、天井付近の無駄な空間まで冷暖房しない
・大空間では温度成層（下が涼しく上が暖かい等）が生じやすく、暖房時は特に足元が寒くなりがち
・観客席のある施設では、着座した人の周辺の気流・温度分布（ドラフト対策）にも配慮が必要

【図解】大空間空調で「無駄な空間」を空調しない発想
天井高10m超の空間の全体を空調しようとすると、使わない上部空間まで冷暖房することになり非効率
○成層空調：居住域（床から2m程度）だけを効率よく空調し、上部は成り行きに任せる
→事務所の床吹出し空調と発想は同じだが、体育館では天井高がさらに大きい分、効果も大きい
→大空間の熱負荷計算では、天井までの容積をそのまま使うと過大設計になりやすい点に注意

━━━━━━━━━━━━━━━━━━━━━━
🔑 外気処理・全熱交換の実務計算
━━━━━━━━━━━━━━━━━━━━━━
・全熱交換器の効率（温度交換効率・湿度交換効率）は機種ごとに異なり、これを踏まえて外気負荷の削減量を試算する
・中間期（内外温度差が小さい時期）は熱交換の効果が薄く、外気冷房とバイパス運転を切り替える制御が有効
・大空間・多人数施設では換気量そのものが大きくなるため、全熱交換器導入による省エネ効果も金額換算で大きくなりやすい
・プール室等、排気に高湿度・腐食性成分を含む室では、全熱交換器のエレメント素材の耐食性・耐水性を確認する必要がある

【図解】全熱交換器導入の効果が大きい室・小さい室
◎効果が大きい：換気量が多く、内外温度差が大きい時期が長い室（事務所・体育館等）
△効果が限定的：排気の汚染度が高く熱交換器が使えない室（厨房・便所等、既出）
→「換気量が多いほど、削減できる外気負荷の絶対量も大きい」という単純な関係を押さえる
→プール室のような高湿度排気は、専用の耐食エレメントを備えた機種でなければ採用できない

⚠ ひっかけ注意
・プール室の結露・腐食対策は「除湿」だけでなく「腐食性ガスへの耐性」も含めて考える必要がある
・大空間の熱負荷計算で天井までの容積をそのまま使うと、成層空調を前提とした設計より過大になる
・中間期は全熱交換の効果が薄く、バイパス運転（外気冷房優先）に切り替える制御が合理的
・体育館の暖房時は「足元が寒く天井付近が暖かい」温度成層が生じやすい（一般居室と同じ感覚は禁物）
・全熱交換器は排気の汚染・腐食性成分の有無によって採用可否が変わる（プール排気は専用機種が必要）

★ここだけ暗記
・プール室＝持続的な水蒸気発生＋腐食性ガス→除湿と耐食性の両方が必須
・大空間空調＝居住域だけを効率的に空調する成層空調・床吹出しが有効
・全熱交換器の効果は換気量が多いほど大きいが、中間期はバイパス運転が合理的
・プール排気には耐食・耐水仕様の全熱交換エレメントが必要`,
