・水道用ポリエチレン管・架橋ポリエチレン管・ポリブテン管：さや管ヘッダー方式（住宅）で主流。可とう性・耐食性◎、紫外線・熱に注意
・硬質ポリ塩化ビニル管（VP）：耐食◎・安価。衝撃・熱・紫外線に弱い

【図解】系統別・管材の定番組合せ
◎給水：塩ビライニング鋼管／ステンレス鋼管／樹脂管（住宅）
◎給湯：銅管／ステンレス鋼管／耐熱性樹脂管（架橋ポリエチレン・ポリブテン）
◎排水：排水用硬質塩ビライニング鋼管／VP管／排水用鋳鉄管（耐火・遮音○）
◎消火：配管用炭素鋼鋼管（白）等・スケジュール管（連結送水管の高圧部）
