        emoji: '🚨',
        body: `断水・停電が発生しても、人は水を使い続けなければ生きていけません。給排水設備の視点からのBCP（事業継続計画）・防災対策を整理します。

▼ゼロから：電気は止まっても、水はもっと止まりやすい
・地震や豪雨等の災害では、電気よりも上下水道の復旧に時間がかかることが少なくありません
・給水設備・排水設備は「止まったらどうするか」をあらかじめ計画しておくことが、建物の防災性能を大きく左右します
・トイレが使えなくなることは、断水そのものより深刻な生活上のダメージになることもあります

━━━━━━━━━━━━━━━━━━━━━━
🔑 断水時の給水確保
━━━━━━━━━━━━━━━━━━━━━━
・受水槽・高置水槽方式（kyuhaisui-01既出）は、水槽に一定量の水を貯めているため、断水直後も一定時間の給水を継続できる
・水道直結方式（直圧・増圧）は、水道本管が断水すると即座に給水不能になる（水槽を持たないことの弱点）
・緊急遮断弁：地震発生時（一定の震度を検知）に、受水槽からの流出を防ぐため自動的に弁を閉じ、水槽内の水を非常用水として確保する装置
・応急給水：給水車・仮設給水栓等による、断水時の外部からの水の供給

【図解】給水方式ごとの断水時の強さ
◎高置水槽方式：水槽の残量分は給水継続可能（ただし電気が止まると揚水ポンプは動かない）
◎直結方式（直圧・増圧）：本管が断水すると即座に給水不能
→「水槽がある方式は災害に強い、水槽がない方式は衛生的だが災害には弱い」というkyuhaisui-01のトレードオフが、防災の視点でも再確認できる
→緊急遮断弁付きの受水槽は、地震直後の飲料水確保という点で特に有効

━━━━━━━━━━━━━━━━━━━━━━
🔑 排水確保とトイレ機能の維持
━━━━━━━━━━━━━━━━━━━━━━
・断水するとトイレの洗浄水が確保できず、また下水道施設の被災により排水が流せなくなることもある
・マンホールトイレ：災害時に、下水道管路に直接接続した仮設トイレを設置できるようにする設備（下水道が健全であることが前提）
・雑用水・雨水利用（kyuhaisui-05既出）は、災害時のトイレ洗浄水として活用できる備えの一つになる
・排水槽・排水ポンプが停電で停止すると、地下階の排水が滞留し、汚水が逆流するリスクがある

【図解】災害時のトイレ機能を守る備えの選択肢
①受水槽の残水＋緊急遮断弁：一定時間の洗浄水を確保
②雑用水・雨水利用システム：非常時のトイレ洗浄水として転用
③マンホールトイレ：下水道が健全なら、仮設トイレとして機能を代替
④携帯トイレ・簡易トイレの備蓄：設備に頼らない最終手段
→複数の備えを組み合わせることで、単一の設備が機能しなくても代替手段を確保する「多重化」の発想が重要

━━━━━━━━━━━━━━━━━━━━━━
🔑 給排水設備のBCP計画
━━━━━━━━━━━━━━━━━━━━━━
・重要施設（病院・防災拠点等）では、井戸水の活用、貯水量の上乗せ等、より高い水準の水源確保が計画されることがある
・非常用発電機（denki-04・09既出）が動いても、揚水ポンプ・排水ポンプへの電源供給が計画されていなければ給排水機能は復旧しない
・給排水設備を非常用発電機の非常負荷（優先的に電源を確保する機器）に含めるかどうかは、BCP計画の重要な検討事項
・災害時の飲料水・生活用水の必要量（1人あたり1日数リットル〜数十リットルの目安）を踏まえた備蓄計画も、建物の防災計画に組み込まれる

⚠ ひっかけ注意
・水槽を持つ給水方式（高置水槽等）は断水直後の給水継続に有利だが、停電すると揚水ポンプが動かせず結局給水できなくなることがある
・マンホールトイレは「下水道管路が被災していないこと」が機能の前提条件
・給排水ポンプ類が非常用発電機の非常負荷に含まれていないと、停電時に給排水機能全体が停止するリスクがある
・雑用水・雨水利用システムは、平常時の節水だけでなく災害時のトイレ洗浄水確保としても機能する
・受水槽の残水量には限りがあるため、長期の断水には応急給水（給水車等）との組み合わせが必要

★ここだけ暗記
・水槽方式は断水直後に強いが、停電でポンプが止まれば結局給水不能になりうる
・緊急遮断弁＝地震時に受水槽の水を非常用水として確保する装置
・マンホールトイレ＝下水道健全時に機能する仮設トイレの選択肢
・給排水ポンプを非常用発電機の非常負荷に含めるかがBCP計画の重要な検討事項`,
