        body: `飲食店・社員食堂・給食センター等の業務用厨房は、一般の給排水計画とは異なる特有の要求事項を持つ、給排水設備の応用分野です。

▼ゼロから：厨房は「水と油の戦場」
・厨房では大量の水を使い、大量の油脂を含む排水が発生します。一般の住宅・オフィスの給排水計画とは桁違いの使用量・負荷になります
・「大量の水をどう供給し、油を含む汚れた排水をどう処理して流すか」が厨房設備計画の核心です

━━━━━━━━━━━━━━━━━━━━━━
🔑 業務用厨房の給水・給湯計画
━━━━━━━━━━━━━━━━━━━━━━
・厨房機器（食器洗浄機、蒸気釜、スチームコンベクションオーブン等）は、一般水栓に比べて大きな給水量・給湯量を必要とすることが多い
・食器洗浄機のすすぎ工程等では高温（60〜80℃程度）の湯が必要になることがあり、給湯計画（kyuhaisui-02既出）と密接に関わる
・厨房用の給水系統は、一般の水回りとは別系統として計画し、ピーク使用時間帯（食事時間帯）の同時使用率を踏まえて配管サイズを決定する
・厨房機器メーカーが指定する必要水圧・給水量を個別に確認し、圧力不足が生じないよう計画する

━━━━━━━━━━━━━━━━━━━━━━
🔑 グリース阻集器の選定と維持管理
━━━━━━━━━━━━━━━━━━━━━━
・グリース阻集器（既出）：厨房排水中の油脂分を分離・捕集し、下水道管の閉塞や公共水域の汚染を防ぐ装置
・阻集器のサイズは、厨房の規模（席数・食数等）や排水量から選定する。過小なサイズでは油脂を十分に分離できない
・阻集器内に捕集された油脂・残渣は定期的に清掃・引き抜きを行う必要があり、清掃を怠ると悪臭や排水管の詰まりの原因になる
・グリース阻集器は、厨房排水系統の他の排水（雑排水等）が混入しないよう、独立した系統として計画することが望ましい

【図解】グリース阻集器が機能しなくなる典型パターン
×サイズ不足：処理能力を超える油脂が流入し、分離しきれず下流へ流出
×清掃不足：捕集した油脂・残渣が満杯になり、新たな油脂を分離できなくなる
×他系統との混合：一般排水と混ざることで、油脂の挙動が想定と異なりトラブルの原因になる
→「適切なサイズ選定」と「定期的な清掃」の両方が揃って初めて、グリース阻集器は機能を発揮する
→阻集器からの悪臭は、多くの場合「清掃不足」のサインとして現れる

━━━━━━━━━━━━━━━━━━━━━━
🔑 排水・換気の特殊対応
━━━━━━━━━━━━━━━━━━━━━━
・厨房排水は油脂・食物残渣を多く含むため、一般の排水管に比べて詰まりやすく、掃除口の配置間隔を密にする等の配慮が有効
・厨房の換気（既出のkucho分野の火気使用室換気）は、調理による熱・油煙・水蒸気を効果的に排出するグリスフィルタ付きレンジフードが基本
・排気ダクト内には油分が付着しやすく、蓄積した油分が火災の燃焼拡大経路になるリスクがあるため、定期的な清掃が防火上も重要
・厨房の床は、大量の水・油を使う特性上、防水・防滑性能の高い仕上げと、床排水（フロアドレン）の適切な配置が求められる

⚠ ひっかけ注意
・厨房機器は一般水栓より大きな給水量・給湯量を要することが多く、専用系統としての計画が基本
・グリース阻集器は「サイズ選定」と「定期清掃」の両方が揃って初めて機能する（どちらか一方では不十分）
・厨房排気ダクトの油分蓄積は、換気性能の低下だけでなく火災の延焼経路にもなりうる（防火上の観点でも清掃が重要）
・グリース阻集器からの悪臭は多くの場合「清掃不足」が原因であり、装置自体の故障とは限らない
・厨房排水系統は他の雑排水系統と分離して計画することが望ましい

★ここだけ暗記
・厨房機器は専用の給水・給湯系統として計画（一般水回りと分離）
・グリース阻集器＝サイズ選定＋定期清掃の両方で初めて機能
・厨房排気ダクトの油分蓄積は換気性能低下と防火上のリスクの両方に関わる
・厨房床は防水・防滑仕上げとフロアドレンの適切な配置が必須`,
