        id: 'kyuhaisui-14',
        title: '寒冷地における給排水設備の凍結対策',
        emoji: '❄️',
        body: `寒冷地の給排水設備には、温暖な地域では意識しない「凍結」という特有のリスクがあります。配管が凍って破裂する仕組みと、その対策を体系的に学びます。

▼ゼロから：水は凍ると「膨らむ」
・水は他の多くの液体と異なり、凍って氷になると体積が約9%膨張します
・配管の中の水が凍ると、この膨張の力で配管自体を内側から押し広げ、破裂させることがあります
・「凍らせない」か「凍っても壊れない」工夫のどちらかが、寒冷地の給排水設計には必須です

━━━━━━━━━━━━━━━━━━━━━━
🔑 凍結が発生する条件
━━━━━━━━━━━━━━━━━━━━━━
・気温が氷点下になり、その状態が一定時間継続すると、屋外配管・外壁沿い配管等で凍結が発生しやすくなる
・水が動いていない（滞留している）配管ほど凍結しやすい（流れている水は凍りにくい）
・屋外に露出した配管、外壁の外側に近い配管、風当たりの強い場所の配管は、特に凍結リスクが高い
・給水管だけでなく、給湯管・消火用配管（屋外に露出する部分）も凍結対策の対象になる

【図解】凍結しやすい場所・しにくい場所の見分け方
◎凍結しやすい：屋外露出配管、外壁直付け配管、地表に近い浅い埋設配管、水の流れが止まりやすい末端部
◎凍結しにくい：室内配管、地中の凍結深度より深い位置の埋設配管、常時水が流れている配管
→「外気にさらされているか」「水が動いているか」の2つの視点で凍結リスクを判断する
→給水栓の末端（屋外散水栓等）は、使用しない時間帯に水が滞留するため、凍結対策の重点箇所になりやすい

━━━━━━━━━━━━━━━━━━━━━━
🔑 凍結防止の具体的手法
━━━━━━━━━━━━━━━━━━━━━━
・保温（断熱）：配管に保温材を巻き、外気からの冷却を防ぐ。ippan-03で学んだ断熱の考え方を配管に応用したもの
・電気ヒーター（ヒーティングケーブル）：配管に沿わせて発熱体を設置し、外気温が下がった際に加温して凍結を防ぐ。保温材と併用することが多い
・水抜き：冬季に使用しない配管系統（屋外散水栓等）の水を抜いておき、配管内に水を残さない対策
・不凍結水栓：地中の凍結深度より深い位置に弁を設け、水栓を閉めると地上部の配管の水が自然に地中側へ抜ける構造の水栓

【図解】凍結対策4手法の使い分け
◎保温：常時使用する配管の基本対策（電気を使わない受動的な対策）
◎電気ヒーター：保温だけでは不足する極寒冷地・重要配管での能動的な加温対策
◎水抜き：冬季に使わない系統（別荘・屋外散水栓等）でのシンプルな対策
◎不凍結水栓：屋外で頻繁に使う水栓（散水栓等）向けの構造的な対策
→「常時使うか、たまに使うか、使わないか」によって適した対策が変わる
→電気ヒーターは停電時に機能を失うため、非常用電源計画（denki分野）との連携も考慮すべき場合がある

━━━━━━━━━━━━━━━━━━━━━━
🔑 凍結深度と埋設配管
━━━━━━━━━━━━━━━━━━━━━━
・凍結深度：その地域で地面が凍結する深さの目安。寒冷地ほど凍結深度は深くなる
・屋外埋設配管は、凍結深度より深い位置に埋設することで、地中の温度が安定し凍結を避けやすくなる
・凍結深度は地域によって大きく異なるため、寒冷地の設計では地域ごとの基準値を確認して配管の埋設深さを決定する
・積雪も断熱材のような役割を果たし、適度な積雪がある地域ではかえって地表付近の温度低下を緩和することもある

⚠ ひっかけ注意
・水は凍ると体積が膨張する（約9%）性質があり、これが配管破裂の直接的な原因
・凍結は「気温の低さ」だけでなく「水が動いていない滞留状態」も重なって起きやすい
・電気ヒーターによる凍結防止は、停電時に機能を失うため非常用電源との連携も検討事項になる
・埋設配管は「凍結深度より深く」埋めることが基本原則（浅いと凍結リスクが残る）
・保温材だけでは極寒冷地では不十分な場合があり、電気ヒーターとの併用が必要になることがある

★ここだけ暗記
・水は凍結時に約9%膨張し、これが配管破裂の原因
・凍結リスクは「外気にさらされているか」「水が滞留しているか」で判断する
・対策4手法：保温／電気ヒーター／水抜き／不凍結水栓（用途に応じて使い分け）
・埋設配管は凍結深度より深い位置に設置するのが基本原則`,
