        body: `受変電設備は契約電力による受電方式の区分、主要機器の役割、保護協調が出題の中心です。

▼ゼロから：ビルの「電気の玄関」
・電力会社は送電ロスを減らすため高い電圧（6,600Vなど）で届けます。建物側で100V・200Vに下げる「変圧」が必要──その玄関口が受変電設備です
・水道でいえば「高圧の本管から減圧して各蛇口へ」の電気版。キュービクルはその機器一式を金属箱に収めたものです
・「どの電圧で受けるか」は契約電力（建物の規模）で決まります

━━━━━━━━━━━━━━━━━━━━━━
🔑 受電方式
━━━━━━━━━━━━━━━━━━━━━━
■ 電圧区分
・低圧：交流600V以下（直流750V以下）
・高圧：交流600V超7,000V以下
・特別高圧：7,000V超

■ 契約電力と受電電圧の目安
・50kW未満：低圧受電（100V/200V）
・50kW以上2,000kW未満：高圧受電（6.6kV）
・2,000kW以上：特別高圧受電（22kV・66kV等）

【図解】電圧区分と受電のめやす
○低圧受電　　：契約50kW未満（コンビニ・小規模店舗）
○高圧受電6.6kV：50kW以上2,000kW未満（中規模ビル・学校）
○特別高圧受電：2,000kW以上（大規模ビル・病院・工場）
→電圧区分：低圧=交流600V以下／高圧=600V超7kV以下／特別高圧=7kV超
→「50kW」と「2,000kW」の2つの境界値が最頻出

■ 受電方式の信頼度
・1回線受電：最も安価、停電リスク大
・ループ受電・本線予備線受電：信頼性向上
・スポットネットワーク受電：最も信頼性が高い。都心の大規模建物
　（ネットワークプロテクタ＝逆電力遮断・無電圧投入・差電圧投入の3特性）

【図解】受電方式の信頼度ランキング
1回線受電　　　　：×1系統故障で停電／安価
本線予備線受電　　：○予備に切替可（瞬時ではない）
ループ受電　　　　：○環状で両側から供給
スポットネットワーク：◎複数回線から常時並列受電・無停電で最強／高価
→スポットネットワークの3特性「逆電力遮断・無電圧投入・差電圧投入」は語句で暗記

━━━━━━━━━━━━━━━━━━━━━━
🔑 主要機器
━━━━━━━━━━━━━━━━━━━━━━
・断路器（DS）：無負荷時のみ開閉可能。点検時の回路切り離し用
・遮断器（CB）：負荷電流・短絡電流とも遮断可能。真空遮断器（VCB）が主流
・高圧交流負荷開閉器（LBS）：負荷電流の開閉可能。限流ヒューズ（PF）と組み合わせて小規模受電設備の主遮断装置に（PF・S形）
・避雷器（LA）：雷サージから機器を保護
・変圧器：油入・モールド・アモルファス（低損失）
・進相コンデンサ（SC）＋直列リアクトル（SR）：力率改善。SRはコンデンサ容量の6%（第5高調波対策）
・計器用変成器：VT（計器用変圧器）・CT（変流器）
　※ CTの二次側は使用中に開放してはならない（高電圧発生・焼損：頻出）

【図解】開閉機器の「できること」比較
◎遮断器CB　：負荷電流○・短絡電流○（何でも切れる＝保護の主役）
○負荷開閉器LBS：負荷電流○・短絡電流×（短絡はヒューズPFに任せる）
×断路器DS　：負荷電流×・無負荷のみ（点検時の縁切り専用）
→「DSで負荷電流を切る」と書かれたら誤り──アークで大事故になる
→操作順序：停電時は CB切→DS切、復電時は DS入→CB入

【図解】保護協調の考え方
事故点に最も近い遮断器だけが動作し、上位は動作しない
末端の分岐→○分岐ブレーカーが遮断（他フロアは停電しない）
幹線事故　→○幹線ブレーカーが遮断
×末端事故で受電用遮断器が先に落ちる＝協調不良（ビル全館停電）
→動作時間と電流の整定を「下位ほど速く・小さく」段付けするのが保護協調

━━━━━━━━━━━━━━━━━━━━━━
🔑 キュービクル式高圧受電設備
━━━━━━━━━━━━━━━━━━━━━━
・金属箱内に受変電機器を収納。省スペース・安全・工期短縮
・屋外設置の場合：保有距離（点検面0.6m以上等）、建物からの離隔3m以上（不燃材外壁等の場合は緩和）
・屋内設置の場合：点検面0.6m以上、操作面1.0m以上等
・電気室は浸水・結露に注意し、上階に水を扱う室を配置しない計画が望ましい
・変圧器等の発熱に対する換気（発熱除去換気量 Q=q/(0.33Δt)）を確保

━━━━━━━━━━━━━━━━━━━━━━
🔑 力率改善・エネルギー管理
━━━━━━━━━━━━━━━━━━━━━━
・力率 = 有効電力 ÷ 皮相電力
・力率改善の効果：電流減少→配電損失減少、変圧器容量の余裕、基本料金割引
・デマンド制御：30分最大需要電力を監視し契約電力超過を防止
・変圧器の効率：鉄損（無負荷損・常時一定）と銅損（負荷損・負荷率の2乗に比例）が等しいとき最大効率

【図解】力率のビール理論
皮相電力［kVA］＝ジョッキ全体（契約・機器容量を決める）
有効電力［kW］＝ビール（実際に仕事をする電力）
無効電力［kvar］＝泡（機器を行き来するだけの電力）
力率＝ビール÷ジョッキ＝kW/kVA
○進相コンデンサで泡を減らす→同じジョッキでビールが増える
→力率改善しても「消費電力量（kWh）そのもの」が減るのではなく、電流と損失が減る

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算実践：力率改善コンデンサの容量算定
━━━━━━━━━━━━━━━━━━━━━━
例題：有効電力300kW、改善前力率0.7を0.95まで改善したい場合
・改善前の無効電力：Q1 = P × tanθ1（θ1は力率0.7に対応する角度、tanθ1 ≒ 1.02）→ Q1 ≒ 300×1.02 ≒ 306kvar
・改善後の無効電力：Q2 = P × tanθ2（力率0.95に対応、tanθ2 ≒ 0.33）→ Q2 ≒ 300×0.33 ≒ 99kvar
・必要な進相コンデンサ容量 ≒ Q1 − Q2 ≒ 306 − 99 ≒ 207kvar

【図解】力率改善計算の考え方（ビール理論の続き）
①有効電力P（ビールの量）は改善前後で変わらない
②無効電力Q（泡の量）だけを、進相コンデンサで打ち消す
③打ち消すべき泡の量＝改善前の泡 − 改善後に許容する泡
→力率角θはcosθ=力率から求まり、tanθの差がそのままコンデンサ容量の目安になる
→実務では力率早見表・力率改善効果表を使い、tanθを都度計算しない場合が多い

⚠ ひっかけ注意
・断路器（DS）は負荷電流を開閉できない──「DSで負荷を切る」は誤り
・CT二次側は「開放禁止」、VT二次側は「短絡禁止」──逆に覚えない
・直列リアクトルは6%（第5高調波対策）
・変圧器の鉄損は負荷にかかわらず一定、銅損は負荷率の2乗
・スポットネットワークは受電用「断路器＋プロテクタ」構成で遮断器レス

★ここだけ暗記
・低圧600V以下・高圧7kV以下・特高7kV超／50kW・2,000kWの境界
・DS=無負荷のみ、CB=短絡も遮断、LBS+PF=小規模の主遮断
・力率=有効/皮相、最大効率は鉄損=銅損
・CT二次開放禁止`,
