        body: `絶縁抵抗・接地抵抗などの試験数値と、消防用設備を支える耐火・耐熱配線を学びます。数値がそのまま出題される得点源です。

▼ゼロから：電気の「健康診断」
・電線の被覆は電気の「防護服」。破れていないかを調べるのが絶縁抵抗測定（メガー）です
・人間ドックの数値に基準値があるように、絶縁抵抗にも電圧区分ごとの合格ラインがあります
・そして火災の中でも消火ポンプへ電気を送り続けるための「燃えても機能を保つ配線」が耐火・耐熱配線です

━━━━━━━━━━━━━━━━━━━━━━
🔑 絶縁抵抗（低圧電路・頻出）
━━━━━━━━━━━━━━━━━━━━━━
・使用電圧300V以下・対地電圧150V以下：0.1MΩ以上
・使用電圧300V以下・対地電圧150V超：0.2MΩ以上
・使用電圧300V超：0.4MΩ以上
・測定は絶縁抵抗計（メガー）で、電路を停電させて実施

【図解】絶縁抵抗の基準値（3段ラダー）
○対地電圧150V以下（単相100V回路等）　：0.1MΩ以上
○300V以下で対地電圧150V超（単3の200V等）：0.2MΩ以上
○300V超（400V配電等）　　　　　　　　：0.4MΩ以上
→「0.1→0.2→0.4」と倍々で上がる──電圧が高いほど厳しい
→分母は「対地電圧か使用電圧か」まで正確に（最初の区分だけ対地電圧）

■ その他の試験
・接地抵抗測定：接地極の抵抗値（A種10Ω・D種100Ω等）を接地抵抗計で確認
・絶縁耐力試験（高圧）：最大使用電圧の1.5倍の電圧を10分間加えて異常のないこと
・継電器試験：過電流継電器（OCR）・地絡継電器（GR）の動作値・動作時間の確認
・シーケンス試験：自家発の自動起動・ATS切替など制御動作の総合確認
・自家用電気工作物：使用前自主検査・定期点検（保安規程による）

【図解】竣工検査のフロー（受変電設備）
外観検査→接地抵抗測定→絶縁抵抗測定→絶縁耐力試験（高圧1.5倍・10分）
→保護継電器試験→インターロック・シーケンス試験→受電→負荷試験
→「壊す可能性の低い試験から順に」が原則
→耐力試験の「1.5倍・10分」は数値セットで暗記

━━━━━━━━━━━━━━━━━━━━━━
🔑 耐火配線・耐熱配線（消防用設備の配線）
━━━━━━━━━━━━━━━━━━━━━━
・耐火配線：火災中も回路を維持する最重要配線
　工法例：耐火電線（FP）を露出配線、または一般電線を金属管に入れ耐火構造の壁等に埋設
　対象例：非常電源から消火ポンプ・スプリンクラー等への電源回路
・耐熱配線：一定の耐熱性を確保する配線
　工法例：耐熱電線（HP）・金属管工事等
　対象例：操作回路・表示灯回路・音響装置回路等
・MIケーブル：無機絶縁ケーブル。最高クラスの耐火性

【図解】耐火と耐熱の使い分け
◎耐火配線（強）：非常電源→消防用設備の「電源回路」（火の中でも動力を送る）
◎耐熱配線（中）：操作・表示・音響など「信号回路」
○一般配線（弱）：それ以外
→「電源=耐火・操作=耐熱」の大原則で整理
→耐火電線の露出配線が認められるのは電線自体が耐火性能を持つため（埋設不要）

━━━━━━━━━━━━━━━━━━━━━━
🔑 電力品質（高調波・ノイズ・瞬低）
━━━━━━━━━━━━━━━━━━━━━━
・高調波：インバータ・整流器等から発生。進相コンデンサの過熱・機器誤動作の原因
　対策：直列リアクトル（6%）・高調波フィルタ・PWMコンバータ
・ノイズ対策：弱電線と強電線の離隔・シールド・ツイストペア・接地
・瞬時電圧低下（瞬低）：系統事故時に数十ms電圧が下がる→UPS・瞬低補償装置で保護
・雷サージ：SPDで保護（内部雷保護）

【図解】高調波のイメージ
きれいな正弦波＋整数倍の周波数成分（第5次・第7次…）＝ゆがんだ波形
発生源：インバータ・UPS・LED電源など半導体機器
被害者：進相コンデンサ（過熱・焼損）・変圧器（損失増）・電子機器（誤動作）
→対策の第一歩が「直列リアクトル6%」（第5高調波対策）──受変電の知識とつながる
→省エネ機器（インバータ）が増えるほど高調波対策が重要になる皮肉な関係

━━━━━━━━━━━━━━━━━━━━━━
🔑 中央監視・ビルマネジメント
━━━━━━━━━━━━━━━━━━━━━━
・中央監視設備：電力・空調・衛生・防災設備の状態監視・遠隔操作・計量
・計測点（ポイント）：状態・警報・計量・操作の4種で整理
・BEMS連携：デマンド監視・スケジュール・帳票（エネルギー管理）
・オープンプロトコル（BACnet等）でマルチベンダ接続
・クラウド監視・遠隔保守の拡大（セキュリティ対策とセット）

━━━━━━━━━━━━━━━━━━━━━━
🔑 経年劣化と更新計画の実務ポイント
━━━━━━━━━━━━━━━━━━━━━━
・絶縁抵抗値は経年で低下する傾向があり、定期測定の記録を蓄積して劣化トレンドを追うことが更新時期の判断材料になる
・ケーブルの劣化は外観だけでは分かりにくく、絶縁抵抗測定や部分放電測定等の診断技術で健全性を評価する
・受変電設備の主要機器（遮断器・変圧器等）には一般的な更新周期の目安があり、竣工図書・点検記録を基に長期修繕計画に組み込む
・更新工事は「稼働中の建物を止めずに」行う必要があることが多く、仮設バイパス電源や夜間・休日施工等の計画が実務上の要点になる

【図解】電気設備の維持管理サイクル
①定期試験（絶縁抵抗・接地抵抗等）でデータを蓄積
②トレンド分析で劣化の進行度を把握
③長期修繕計画に基づき、更新時期を計画的に前倒しで検討
④更新工事は停電を最小化する施工計画（仮設・夜間施工等）とセットで実施
→「壊れてから直す」のではなく「データに基づき壊れる前に計画的に更新する」のが現代の維持管理の考え方
→中央監視・BEMSのデータは、この劣化トレンド分析にも活用できる

⚠ ひっかけ注意
・絶縁抵抗0.1/0.2/0.4MΩの区分──「対地電圧150V」の条件を落とさない
・絶縁耐力試験は「最大使用電圧の1.5倍を10分間」
・耐火配線と耐熱配線の対象回路の入れ替え（電源=耐火・操作=耐熱）
・高調波対策のリアクトルは「直列」6%──並列ではない
・測定は停電状態で（メガーは充電部に印加する試験器）

★ここだけ暗記
・絶縁抵抗：0.1（150V以下）・0.2（300V以下）・0.4MΩ（300V超）
・耐力試験：1.5倍・10分
・電源回路=耐火配線／操作・音響=耐熱配線
・高調波→直列リアクトル6%・コンデンサ過熱に注意`,
