        title: '情報通信・セキュリティ設備の詳細',
        emoji: '📡',
        body: `LAN・電話交換・映像監視・入退室管理──「弱電」と総称される情報通信系の設備を、それぞれの役割から詳しく見ていきます。

▼ゼロから：「強電」は動力、「弱電」は情報を運ぶ
・電灯・動力（強電）が「エネルギー」を運ぶのに対し、弱電は「情報」を運びます
・情報の中身は音声（電話）・映像（監視カメラ）・データ（LAN）・信号（センサー）とさまざまです
・現代のビルでは、これらが1本のLANケーブル（IP化）に統合される流れが進んでいます

━━━━━━━━━━━━━━━━━━━━━━
🔑 構内情報通信網の設計
━━━━━━━━━━━━━━━━━━━━━━
・幹線系（基幹配線）：MDF（主配線盤）からEPS・PS経由でIDF（中間配線盤）へ光ファイバー等で接続
・水平配線系：IDFから各執務エリアの情報コンセントまで、UTPケーブル（メタルケーブル）で配線
・構造化配線システム（SCS）：将来のレイアウト変更に柔軟に対応できるよう、あらかじめ格子状に配線を敷設しておく考え方
・PoE（Power over Ethernet）：LANケーブルで通信と電力供給を同時に行う技術。無線LANアクセスポイント、ネットワークカメラ、IP電話機等に給電できる

【図解】構内LANの配線階層
[MDF：建物の情報の玄関口]
　↓幹線（光ファイバー・電磁誘導の影響を受けにくい）
[IDF：フロアごとの中継点]
　↓水平配線（UTPケーブル）
[情報コンセント：机上のPC等へ]
→「幹線は長距離・大容量だから光」「水平は短距離だからメタルで十分」という使い分けの理屈
→PoEにより、電源工事なしでカメラ・APを設置できる場所の自由度が上がる

━━━━━━━━━━━━━━━━━━━━━━
🔑 映像監視・入退室管理システム
━━━━━━━━━━━━━━━━━━━━━━
■ 映像監視（防犯カメラ）
・ネットワークカメラ（IPカメラ）が主流：LAN経由で映像を伝送し、レコーダー（NVR）またはクラウドに録画
・旧来のアナログカメラは同軸ケーブルで映像を伝送し、DVR（デジタルビデオレコーダー）に録画
・カメラの設置目的により「犯罪の抑止」「証拠の記録」「異常の検知（AI画像解析）」の重点が変わる

■ 入退室管理
・カード認証（非接触ICカード）、生体認証（指紋・静脈・顔認証）、暗証番号等の組合せ
・電気錠：常時施錠で認証時のみ解錠する方式が一般的。停電時・火災時の解錠方式（フェールセーフ／フェールセキュア）を用途で使い分ける
・フェールセーフ：停電時は「解錠」される方式（避難経路等、安全優先の扉に採用）
・フェールセキュア：停電時も「施錠」を維持する方式（重要室・機密室等、防犯優先の扉に採用）

【図解】フェールセーフとフェールセキュアの使い分け
◎フェールセーフ：電源が切れたら「開く」→避難経路上の扉（人命最優先）
◎フェールセキュア：電源が切れても「閉じたまま」→サーバー室・貴重品室等（防犯・機密最優先）
→「安全（避難）を優先するか、防犯（侵入防止）を優先するか」で選び方が逆になる
→防災計画上、避難経路の電気錠は火災信号連動で強制解錠されるのが原則（bousaiの防災連動と直結）

━━━━━━━━━━━━━━━━━━━━━━
🔑 構内交換機・その他通信インフラ
━━━━━━━━━━━━━━━━━━━━━━
・PBX（構内交換機）：建物内の内線電話を交換する装置。近年はIP-PBX（LAN上で音声を扱うIP電話）への移行が進む
・ビジネスホン：小規模向けの簡易な内線電話システム
・構内無線LAN：フロア全体をカバーするようアクセスポイントを配置。電波干渉やチャンネル設計、セキュリティ（暗号化）への配慮が必要
・電気通信事業者の引込み：MDFの手前に通信事業者の設備（回線終端装置等）が設置される

■ 情報化への対応（ICT）
・BEMS・映像監視・入退室・空調制御等、従来は個別だったシステムをLAN上で統合管理する動きが拡大
・サイバーセキュリティ：building automationシステムがネットワークにつながることで、物理セキュリティだけでなく情報セキュリティ対策（不正アクセス防止等）も設備計画の一部になっている

⚠ ひっかけ注意
・幹線系は光ファイバー、水平配線系はUTPケーブルという役割分担を逆にしない
・フェールセーフ（停電時解錠・避難優先）とフェールセキュア（停電時施錠維持・防犯優先）は正反対の設計思想
・避難経路上の電気錠は火災信号で強制解錠されるのが原則──「防犯優先で締め切る」設計は避難上危険
・ネットワークカメラ（IP）とアナログカメラでは伝送方式・録画機器（NVRかDVRか）が異なる
・PoEは電力供給の技術であり、通信速度そのものを向上させる技術ではない

★ここだけ暗記
・幹線＝光ファイバー（MDF-IDF間）、水平配線＝UTP（IDF-情報コンセント間）
・PoE＝LANケーブルで通信＋給電（カメラ・AP等）
・フェールセーフ＝停電時解錠（避難優先）／フェールセキュア＝停電時施錠維持（防犯優先）
・避難経路の電気錠は火災信号で強制解錠が原則`,
