        body: `denki-02で学んだA〜D種接地工事をさらに掘り下げ、医療施設等で求められる等電位ボンディングの考え方まで学びます。「電気を安全に大地へ逃がす」技術の総仕上げです。

▼ゼロから：なぜ「アース」が必要なのか
・電気機器の金属製の外箱に、万一漏電（絶縁不良で電気が漏れること）が起きると、外箱に触れた人が感電する危険があります
・接地（アース）は、この漏れた電気を安全に大地へ逃がし、人体に危険な電圧がかからないようにする仕組みです
・複数の金属部分が「同じ電位（電気的に同じ状態）」になるよう結ぶことを等電位ボンディングと呼び、感電防止をさらに一歩進めた考え方です

━━━━━━━━━━━━━━━━━━━━━━
🔑 接地の目的による分類
━━━━━━━━━━━━━━━━━━━━━━
・保安接地：機器の外箱等を接地し、漏電時の感電・火災を防止する（denki-02のA・C・D種はこれに該当）
・系統接地：変圧器の低圧側中性点等を接地し、高低圧混触時に低圧側の電位が異常上昇するのを抑制する（B種）
・機能接地：通信機器・情報機器等が正常に機能するために必要な接地（ノイズ対策等）
・雷保護用接地：避雷設備の接地極（denki-04・07既出のLPSと関連）

【図解】接地の4つの目的の整理
◎保安接地（A・C・D種）：人を守る（漏電時の感電防止）
◎系統接地（B種）：電力系統を守る（高低圧混触時の異常電圧抑制）
◎機能接地：機器を正しく動かす（ノイズ対策等）
◎雷保護用接地：雷から機器・建物を守る
→「誰を・何を守るための接地か」で目的を整理すると、denki-02のA〜D種の暗記がより立体的に理解できる

━━━━━━━━━━━━━━━━━━━━━━
🔑 等電位ボンディング
━━━━━━━━━━━━━━━━━━━━━━
・等電位ボンディング：建物内の金属部分（配管・鉄骨・電気設備の接地系統等）を導体で相互に接続し、電位差をなくす（同じ電位にそろえる）技術
・電位差があると、異なる金属部分に同時に触れた人の体に電流が流れる危険がある。等電位ボンディングはこれを防ぐ
・医用接地（医療用接地）：手術室・ICU等、患者の体に直接触れる医療機器が多い室で、より厳格な等電位ボンディングが求められる
・医用接地方式：患者の周囲にある金属部分すべてをごく低い電位差に保つことで、生命維持装置等使用時のわずかな漏れ電流による事故（ミクロショック）を防止する

【図解】一般の接地と医用接地の要求水準の違い
◎一般の接地：漏電時の感電・火災防止が主目的（denki-02のA〜D種）
◎医用接地：患者の体内に直接電流が流れうる環境のため、極めて小さい漏れ電流でも危険という前提で、より厳格な等電位化を要求
→「触れるだけの感電」より「体内に直接電流が流れる状況」の方が、はるかに小さい電流でも危険という違いを理解する
→医用コンセント（denki-03既出の色区分）と医用接地は、手術室・ICU等の電気安全のための一体的な仕組み

━━━━━━━━━━━━━━━━━━━━━━
🔑 情報機器・データセンターの接地
━━━━━━━━━━━━━━━━━━━━━━
・情報通信機器は、ノイズによる誤動作を防ぐため、良好な接地（機能接地）が求められる
・複数の機能接地・保安接地を1つの接地システムに統合する「共用接地」方式が、近年の建物では一般的
・接地線が長い・接地抵抗が高いと、ノイズ対策としての機能接地の効果が薄れることがある
・データセンター・電算機室では、フリーアクセスフロアの金属パネル等も含めた等電位化が計画されることがある

⚠ ひっかけ注意
・A〜D種の保安接地とB種の系統接地は「守る対象」が異なる（人を守る vs 電力系統を守る）
・等電位ボンディングは「接地する」こととは少し異なり、複数の金属部分どうしの電位差をなくすことが目的
・医用接地は一般の接地基準よりも厳しい水準が求められる（わずかな漏れ電流でも患者にとって危険なため）
・機能接地（ノイズ対策）と保安接地（感電防止）は目的が異なるが、実務では共用接地として統合されることが多い
・接地線が長い・接地抵抗が高いと、機能接地としての効果（ノイズ対策）が低下する

★ここだけ暗記
・接地の4目的：保安（人を守る）・系統（電力系統を守る）・機能（機器を守る）・雷保護（建物を守る）
・等電位ボンディング＝金属部分どうしの電位差をなくす技術（感電防止の発展形）
・医用接地＝手術室・ICU等で、患者への微小な漏れ電流事故（ミクロショック）を防ぐための厳格な接地
・現代の建物では複数の接地目的を統合する「共用接地」が一般的`,
