        body: `bousai-01で学んだ非常放送設備を、電気設備の視点から掘り下げます。増幅器・スピーカー・配線をどう設計すれば、火災時に確実に声が届くかを考えます。

▼ゼロから：「聞こえる」ことは当たり前ではない
・非常放送は、火災時に在館者へ避難を呼びかける最後の砦の一つです
・しかし配線が1本切れただけで一部のスピーカーから音が出なくなるような設計では、いざというとき機能しません
・「音を作る（増幅器）」「音を届ける（配線・スピーカー）」「壊れても機能を保つ（配線の耐熱化）」という3つの視点で設計します

━━━━━━━━━━━━━━━━━━━━━━
🔑 非常放送設備の基本構成
━━━━━━━━━━━━━━━━━━━━━━
・増幅器：マイク・自動火災報知設備からの信号を増幅し、スピーカーへ送る中心的な機器
・スピーカー：各階・各室に設置され、放送内容を音として出力する。L級・M級・S級等、出力レベルによる区分がある
・配線：増幅器からスピーカーまでの配線には、denki-06で学んだ耐熱配線（操作・音響回路に該当）が適用される
・カットリレー（既出）：火災時に一般放送・BGM回線を遮断し、非常放送を優先させる装置

【図解】非常放送設備の信号の流れ
自火報（火災信号）またはマイクからの音声
→［増幅器］で増幅
→［配線（耐熱配線）］を経由
→［各スピーカー］で音として出力
→カットリレーが一般放送・BGMを自動遮断し、非常放送を優先
→「火災を感知したら自動的に必要な階へ放送が流れる」という自動化の仕組みと、人が肉声で呼びかけられる仕組みの両方を備える

━━━━━━━━━━━━━━━━━━━━━━
🔑 系統設計と信頼性確保
━━━━━━━━━━━━━━━━━━━━━━
・非常放送設備は階ごと・区域ごとに系統を分け、出火階とその直上階等、必要な区域に優先的に放送する区分放送が行われることが多い（bousai-01の自火報の区分鳴動と同様の発想）
・配線の断線・短絡が発生しても、一部の系統だけの影響にとどまるよう、系統を適切に分割することが信頼性向上につながる
・非常放送用のスピーカー配線に一般の弱電配線が混在すると、誤配線・干渉のリスクが生じるため、系統の独立性を保つ設計が求められる
・非常電源（bousai-06既出）からの給電も、他の一般負荷と共倒れにならないよう、専用回路として計画される

━━━━━━━━━━━━━━━━━━━━━━
🔑 スピーカーの配置と音圧設計
━━━━━━━━━━━━━━━━━━━━━━
・スピーカーは、各部分から一定の距離内で必要な音圧が確保できるよう配置間隔を計画する（自火報の地区音響装置の水平距離25m以下という考え方と類似）
・天井の高い空間・騒音の大きい環境（機械室等）では、通常より出力の大きいスピーカー（L級等）を選定する
・複数のスピーカーから同じ音が時間差で届くと、反響・エコーにより聞き取りにくくなることがあり、配置・音量バランスの調整が必要
・音声だけでなく、非常時の緊急地震速報等、他の警報システムとの連携が求められる場合もある

⚠ ひっかけ注意
・非常放送の配線には、denki-06で学んだ耐熱配線が適用される（操作・音響回路に該当）
・区分放送は、出火階に近い区域を優先する発想で系統が分けられる（自火報の区分鳴動と同じ考え方）
・非常放送用の配線に一般弱電配線を混在させると、系統の独立性が損なわれるリスクがある
・非常放送設備の非常電源は、他の一般負荷と共倒れにならないよう専用回路として計画することが望ましい
・スピーカーの配置は「音圧が届く距離」を踏まえて計画する必要があり、単純に均等配置すればよいわけではない

★ここだけ暗記
・非常放送の流れ：自火報またはマイク→増幅器→耐熱配線→スピーカー、カットリレーで一般放送を遮断
・区分放送＝出火階に近い区域を優先する系統分割（自火報の区分鳴動と同じ発想）
・非常放送の配線・電源は一般設備と独立させ、系統障害の影響範囲を限定する
・スピーカー配置は音圧が届く距離を踏まえて計画する`,
