        emoji: '⚠️',
        body: `kyuhaisui-15で見た「事故から学ぶ」視点を、電気設備にも当てはめます。過去の電気事故のパターンを知ることは、暗記した基準の意味を深く理解する近道です。

▼ゼロから：電気事故は「見えない」からこそ怖い
・水漏れは目に見えますが、漏電・絶縁劣化は外から見ただけでは分かりません
・「見えないリスク」に対して、定期的な測定・点検という形で「見える化」する仕組みが、denki-06で学んだ絶縁抵抗測定等の各種試験です
・過去の電気火災・感電事故の多くは、この「見えないリスク」を放置した結果として起きています

━━━━━━━━━━━━━━━━━━━━━━
🔑 トラッキング現象による火災
━━━━━━━━━━━━━━━━━━━━━━
・トラッキング現象：コンセントとプラグの間に長期間蓄積したほこりが湿気を吸収し、微小な放電（トラッキング）を繰り返すことで発熱・出火する現象
・長期間差しっぱなしのプラグ（家具の裏の配線等、清掃が行き届きにくい場所）で特に発生しやすい
・対策：コンセント・プラグまわりの定期的な清掃、防塵・防湿型のコンセントカバーの使用等
・これは特別な機器の故障ではなく、日常の使い方・清掃の不足という「運用面」から生じる火災原因である点が特徴的

【図解】トラッキング現象が起きるプロセス
①コンセント・プラグの隙間にほこりが蓄積
②湿気を吸ってほこりが微弱な導電性を持つ
③微小な放電（トラッキング）が繰り返される
④発熱が進行し、最終的に発火する
→「差しっぱなし」「掃除しない」という日常的な習慣が、電気火災の原因になりうることを示す典型事例
→denki-06で学んだ絶縁抵抗測定は固定配線・機器の絶縁劣化を検出するものだが、トラッキングはより身近なコンセント周りの日常管理の問題

━━━━━━━━━━━━━━━━━━━━━━
🔑 分電盤・幹線の過負荷による事故
━━━━━━━━━━━━━━━━━━━━━━
・タコ足配線等により、1つの回路の許容電流（denki-02既出）を超える負荷を接続すると、配線が異常発熱し、火災の原因になることがある
・増設・改修工事の際に、既存の幹線・分電盤の容量を確認せずに負荷を追加すると、想定外の過負荷状態を招くことがある
・過電流遮断器（ブレーカー）は、この過負荷を検出して自動的に回路を遮断する安全装置だが、遮断器の選定・整定が不適切だと十分に機能しないことがある
・建物の用途変更・テナント入替え（hoki-07既出）に伴う電気設備の負荷増加は、この過負荷リスクの典型的な発生場面である

━━━━━━━━━━━━━━━━━━━━━━
🔑 感電事故の典型パターン
━━━━━━━━━━━━━━━━━━━━━━
・漏電した金属製の機器外箱に人が触れ、体を通じて大地へ電流が流れることで感電する
・接地（denki-02・11既出）が適切に行われていれば、漏電時の電位上昇が抑えられ、感電の危険性が大きく低減する
・水気のある場所（浴室・厨房・屋外等）では、人体の抵抗が下がるため、同じ漏電量でもより危険な感電につながりやすい
・漏電遮断器（既出）は、漏電を検出して瞬時に電路を遮断し、感電事故を未然に防ぐための重要な安全装置

【図解】感電を防ぐ多重の安全対策
①絶縁：そもそも電気が漏れないようにする（配線・機器の絶縁性能）
②接地：漏れた電気を安全に大地へ逃がし、電位上昇を抑える
③漏電遮断器：漏電を検出したら瞬時に電気を止める
→「漏らさない（絶縁）」「逃がす（接地）」「止める（遮断器）」の3段階の安全対策が重なって初めて、感電リスクを十分に低減できる
→どれか1つが欠けても、事故のリスクは大きく高まる

⚠ ひっかけ注意
・トラッキング現象は機器の故障ではなく、コンセント周りの清掃不足という日常的な要因で発生する
・過負荷事故は、増設・改修時に既存幹線・分電盤の容量確認を怠ることが典型的な原因の一つ
・接地・漏電遮断器はそれぞれ役割が異なり、どちらか一方だけでは感電防止の効果は限定的
・水気のある場所は人体の抵抗が下がり、同じ漏電量でもより危険な感電につながりやすい
・電気事故の多くは「見えないリスク」の放置が原因であり、定期点検・測定による見える化が予防の鍵となる

★ここだけ暗記
・トラッキング現象＝コンセント周りのほこり・湿気による微小放電からの出火（清掃不足が原因）
・過負荷事故＝既存幹線・分電盤の容量確認を怠った増設・改修が典型的な原因
・感電防止の3段階：絶縁（漏らさない）＋接地（逃がす）＋漏電遮断器（止める）
・電気事故予防の鍵は「見えないリスク」を定期点検・測定で見える化すること`,
