延焼が速い大空間？（舞台部）→YES→開放型（一斉開放弁）
天井高10m超（物販6m超）？→YES→放水型ヘッド
それ以外の一般室→湿式（即時放水・最も確実）
→「時間遅れ」の順：湿式（なし）＜予作動・乾式（充水時間）──速さと安全のトレードオフ

