━━━━━━━━━━━━━━━━━━━━━━
・非常電源の容量計画は「接続する消防用設備等をすべて同時に、有効に作動できる時間」を基準に決める
・複数の消防用設備（スプリンクラー・排煙機・非常用照明等）が同時に作動する想定を踏まえ、それぞれの必要電力を積み上げて自家発電機・蓄電池の容量を決定する
・非常電源の起動シーケンス：停電検知→自家発電機の始動→電圧確立（40秒以内）→負荷への給電開始、という一連の流れを確実に行うための制御（自動始動盤・ATS）が重要
・容量不足を避けるため、将来の設備増設を見込んだ余裕（増設用の予備回路等）を持たせる設計も実務では行われる

【図解】非常電源容量を決めるまでの積み上げ
①同時に作動する消防用設備等をリストアップ（スプリンクラーポンプ・排煙機・非常用照明・自火報等）
②それぞれの必要電力（kW）を合計
③力率・将来増設分の余裕を見込んで自家発電機の定格出力を決定
④蓄電池は「電圧確立までの40秒」をつなぐ容量、または誘導灯等の短時間バックアップ容量として別途計画
→「一番大きい設備の電力だけ見る」のではなく「同時作動するすべての設備の合計」で容量を決めるのが基本
→非常電源の設計ミスは、火災時に複数の防災設備が共倒れになるリスクに直結する

