・いわゆる「雑居ビル」の火災で被害が拡大した教訓から、複合用途防火対象物の避難管理・防火管理は特に重視されている

【図解】単一用途と複合用途の防火管理の違い
◎単一用途（例：オフィスビル1棟すべて事務所）：1人の防火管理者が建物全体を管理しやすい
◎複合用途（例：1階飲食店・2階物販・3〜5階事務所）：テナントごとに管理権原者が分かれる→統括防火管理者による全体調整が必須
