        body: `排煙設備や防火区画がなぜそのように設計されるのかを理解するには、火災そのものが時間とともにどう成長するかという「火災性状」の知識が土台になります。

▼ゼロから：火は一定の速さでは大きくならない
・小さなろうそくの炎が、ある瞬間に部屋全体を覆う炎に急変することがあります。この急激な変化が「フラッシュオーバー」です
・火災の成長は、じわじわ大きくなる時間帯と、一気に爆発的に拡大する瞬間があり、これを理解すると排煙・避難設計の「なぜ」が見えてきます

━━━━━━━━━━━━━━━━━━━━━━
🔑 区画火災の成長過程
━━━━━━━━━━━━━━━━━━━━━━
・出火期：着火直後、燃焼範囲が限定的で、煙・熱の発生も少ない段階
・成長期：可燃物への延焼が進み、煙・熱が徐々に増加していく段階
・フラッシュオーバー：天井付近に蓄積した高温の可燃性ガスが一気に着火し、室内全体が爆発的に燃え広がる現象
・最盛期：室内の可燃物のほとんどが燃焼し、火災が最大規模になる段階
・減衰期：燃えるものが少なくなり、火勢が衰えていく段階

【図解】区画火災の時間経過と危険性の変化
出火期（小さな炎）→成長期（煙・熱が増加）→フラッシュオーバー（室内全体が一気に炎上）→最盛期→減衰期
→避難はフラッシュオーバーが起きる「前」に完了させることが、避難安全計画の絶対条件
→フラッシュオーバー後の室内は、人が生存できる環境ではなくなる（避難ではなく消火活動の領域に移る）
→bousai-06で学んだ避難安全検証法の「避難完了時間＜煙が避難上支障のある高さまで降下する時間」は、この成長過程のどこかで避難を終える設計思想

━━━━━━━━━━━━━━━━━━━━━━
🔑 煙の挙動の科学
━━━━━━━━━━━━━━━━━━━━━━
・煙の浮力：燃焼で温められた煙は周囲の空気より軽くなり、上昇する（プルーム上昇流）
・煙層の形成：上昇した煙は天井にぶつかって水平に広がり、天井付近から徐々に下方へ蓄積していく（煙層降下）
・煙突効果（スタック効果）：建物内外の温度差により、階段室・エレベーターシャフト等の竪穴区画で上昇気流が生じる現象。火災時には煙をより速く上階へ運んでしまう
・中性帯：竪穴区画内で、上昇気流と下降気流の境目となる高さ。この高さより下では外気が流入し、上では煙が流出する

【図解】煙突効果が火災時に危険な理由
①火災の熱で竪穴区画内の空気が温められ軽くなる
②煙突効果（温度差による上昇気流）が煙を強力に上階へ引き上げる
③出火階から離れた上階まで、煙が急速に到達する
→階段室・EVシャフトが「区画」されていない、または区画が不完全だと、この煙突効果が火災の被害を拡大させる
→竪穴区画（bousai-04で学んだ防火区画の一種）の重要性は、この煙突効果を断ち切ることにもある

━━━━━━━━━━━━━━━━━━━━━━
🔑 排煙設計への応用
━━━━━━━━━━━━━━━━━━━━━━
・排煙設備の目的は、煙層が「避難上支障のある高さ」まで降下する前に、煙を屋外へ排出して煙層の高さを保つこと
・防煙垂れ壁（防煙区画）は、煙を一定の範囲に閉じ込め、拡散を防ぎながら排煙口へ誘導する役割を持つ
・排煙口の能力（120m³/min以上等）は、想定される火災規模で発生する煙の量に対して、煙層の降下を抑えられるよう設定されている
・大空間・アトリウムでは、煙の蓄積量が大きくなるため、より高度な煙制御計画（区画避難安全検証法等）が必要になることが多い

⚠ ひっかけ注意
・フラッシュオーバーは「徐々に」ではなく「一気に・爆発的に」室内全体が炎上する現象
・煙突効果は温度差で生じる自然現象であり、竪穴区画が不十分だと火災の煙拡散を助長する
・避難安全計画は「フラッシュオーバー前」に避難を完了させることを前提としている
・煙は熱による浮力で上昇し天井にたまる──煙が下に沈むのは煙が冷えて浮力を失った後の段階
・排煙設備は「煙をゼロにする」のではなく「煙層の高さを避難上安全な位置に保つ」ことが目的

★ここだけ暗記
・区画火災の進行：出火期→成長期→フラッシュオーバー→最盛期→減衰期
・避難は「フラッシュオーバー前」に完了させるのが避難安全計画の大前提
・煙突効果＝竪穴区画内の温度差による上昇気流。煙の拡散を加速させる
・排煙の目的＝煙層の高さを避難上安全な位置に保つこと（煙をゼロにすることではない）`,
